   bezugsweg_id                        INTEGER     NOT NULL COMMENT 'Bezugsweg der Ware (direkt vom Lieferanen = 1 oder über Zentrallager = 4).',
   wup_bereinigt_fg                    INTEGER     NOT NULL DEFAULT 0 COMMENT 'Flag: Zeigt ob die Kennzahlen für diesen Markt in die "bereinigte" Sicht einfließen dürfen, d.h. der Markt hatte in den letzten 12 Monaten vor dem Wochenbeginn der aktuellen Auwertung geöffnet und wird in der betrachteten Woche_2 nicht permanent geschlossen (zieht höchstens um).',
   menge                               NUMBER(29,3)     NOT NULL COMMENT 'Menge der Artikelbewegung (kann in Stück oder bei Gewichtsartikeln in KG sein).',
   umsatz_netto                        NUMBER(29,4)     NOT NULL COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag.',
   umsatz_mwst_betrag                  NUMBER(29,4)     NOT NULL COMMENT 'Der Mehrwertsteuerbetrag wird hier redundant abgelegt. Er ist eigentlich pro Artikel_2 als Mehrwertsteuersatz im Artikelstamm ersichtlich muss aber hier aus Performancegründen auch stehen.',
   ek_mep                              NUMBER(29,4)     COMMENT 'Markteinstandspreis (Bedeutung vgl. Kalkulationsschema).',
   ek_mep_vor_fwu                      NUMBER(29,4)     COMMENT 'Markteinstandspreis vor Festwertumlage: Mit Einführung der Festwertumlage in KMO braucht es einen "alten" EK3Netto ohne die Festwertumlage als Vergleichswert. Dieser Wert wird aus SAP über ZEKP.MEPOL geliefert.',
   ek_mep_vor_fwu_konz                 NUMBER(29,4)     COMMENT 'Markteinstandspreis vor Festwertumlage in Konzernwährung, wenn Landeswährung davon abweicht. Mit Einführung der Festwertumlage in KMO braucht es einen "alten" EK3Netto ohne die Festwertumlage als Vergleichswert. Dieser Wert wird aus SAP über ZEKP.MEPOL geliefert.',
   einstandspreis                      NUMBER(29,4)     COMMENT 'Kaufland Einstandspreis (Bedeutung vgl. Kalkulationsschema).',
   ek_nettonetto                       NUMBER(29,4)     COMMENT 'Einkaufspreis nettonetto (Bedeutung vgl. Kalkulationsschema).',
   wrg_id                              VARCHAR(3)       NOT NULL COLLATE 'en-ci' COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR.',
   umrechnungskurs_hist                NUMBER(29,5)     NOT NULL DEFAULT 0 COMMENT 'Historischer Berichtskurs aus dbp_data.kurs_2 ',
   diff_einstandspreis_konz            NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Einstandspreis.',
   diff_ek_brutto_konz                 NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Einkaufspreis brutto.',
   diff_ek_gld_konz                    NUMBER(29,4)     COMMENT 'Differenz zum gleitenden Durchschnittspreis in Konzernwährung.',
   diff_ek_kal_basis_konz              NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Einkaufspreis Kalkulationsbasis.',
   diff_ek_mep_konz                    NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Einkaufspreis Markteinstandspreis.',
