   diff_ek_netto_konz                  NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Einkaufspreis netto.',
   diff_ek_nettonetto_konz             NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Einkaufspreis nettonetto.',
   diff_logkostenzuschlag_konz         NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Logistikkostenzuschlag.',
   diff_umsatz_mwst_betrag_konz        NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Mehrwertsteuerbetrag.',
   diff_umsatz_netto_konz              NUMBER(29,4)     COMMENT 'Von der Konzernwährung abweichender Umsatz netto.',
